import QRCode from "qrcode";
import { appBaseUrl, paymentConfig } from "./config";
import type { Invoice } from "./types";

export function invoicePayUrl(invoiceId: string) {
  return `${appBaseUrl()}/pay/${invoiceId}`;
}

/** UPI deep link when PAYMENT_UPI_ID is set; otherwise the Remitra pay page URL. */
export function buildPayablePayload(invoice: Invoice) {
  const { upiId, payeeName, notePrefix } = paymentConfig();
  const note = `${notePrefix}-${invoice.id.slice(0, 8)}`;

  if (upiId) {
    const params = new URLSearchParams({
      pa: upiId,
      pn: payeeName,
      am: invoice.amount.toFixed(2),
      cu: invoice.currency === "INR" ? "INR" : invoice.currency,
      tn: note,
    });
    return {
      kind: "upi" as const,
      payload: `upi://pay?${params.toString()}`,
      note,
      upiId,
      payeeName,
    };
  }

  return {
    kind: "link" as const,
    payload: invoicePayUrl(invoice.id),
    note,
    upiId: "",
    payeeName,
  };
}

export async function buildPaymentQrDataUrl(invoice: Invoice) {
  const built = buildPayablePayload(invoice);
  const dataUrl = await QRCode.toDataURL(built.payload, {
    margin: 2,
    width: 280,
    color: { dark: "#14221c", light: "#f7faf7" },
  });
  return { ...built, dataUrl, payUrl: invoicePayUrl(invoice.id) };
}
